import unittest

from hourglass.models import Span
from hourglass.gaps import find_gaps

OPEN = Span(8 * 60, 18 * 60)


class FindGapsTests(unittest.TestCase):
    def test_no_spans_is_one_gap(self):
        self.assertEqual(find_gaps([], OPEN), ["gap 08:00-18:00 (600 min)"])

    def test_gap_in_the_middle(self):
        spans = [Span(480, 720), Span(780, 1080)]
        self.assertEqual(find_gaps(spans, OPEN), ["gap 12:00-13:00 (60 min)"])

    def test_gaps_at_both_ends(self):
        labels = find_gaps([Span(540, 1020)], OPEN)
        self.assertEqual(labels, ["gap 08:00-09:00 (60 min)", "gap 17:00-18:00 (60 min)"])

    def test_overlapping_and_touching_leave_no_gap(self):
        spans = [Span(480, 700), Span(600, 800), Span(800, 1080)]
        self.assertEqual(find_gaps(spans, OPEN), [])

    def test_unordered_input(self):
        spans = [Span(780, 1080), Span(480, 720)]
        self.assertEqual(find_gaps(spans, OPEN), ["gap 12:00-13:00 (60 min)"])

    def test_span_before_opening_raises(self):
        with self.assertRaises(ValueError):
            find_gaps([Span(420, 600)], OPEN)

    def test_span_after_closing_raises(self):
        with self.assertRaises(ValueError):
            find_gaps([Span(600, 1100)], OPEN)
